(2, 4, 'Do you have any laptops in stock?', '```json\n{\n  \"type\": \"sql\",\n  \"action\": \"search_products\",\n  \"query\": \"SELECT p.id, p.product_name, p.selling_price, p.discount_price, p.product_quantity, p.image_one FROM products p JOIN categories c ON p.category_id = c.id WHERE c.category_name = \'Laptops\' AND p.product_quantity > 0 AND p.status = 1 LIMIT 20\"\n}\n```', '{\"candidates\": [{\"content\": {\"parts\": [{\"text\": \"```json\\n{\\n  \\\"type\\\": \\\"sql\\\",\\n  \\\"action\\\": \\\"search_products\\\",\\n  \\\"query\\\": \\\"SELECT p.id, p.product_name, p.selling_price, p.discount_price, p.product_quantity, p.image_one FROM products p JOIN categories c ON p.category_id = c.id WHERE c.category_name = \'Laptops\' AND p.product_quantity > 0 AND p.status = 1 LIMIT 20\\\"\\n}\\n```\"}], \"role\": \"model\"}, \"finishReason\": \"STOP\", \"index\": 0}], \"usageMetadata\": {\"promptTokenCount\": 554, \"candidatesTokenCount\": 114, \"totalTokenCount\": 1295, \"promptTokensDetails\": [{\"modality\": \"TEXT\", \"tokenCount\": 554}], \"thoughtsTokenCount\": 627, \"serviceTier\": \"standard\"}, \"modelVersion\": \"gemini-2.5-flash\", \"responseId\": \"JMQ3atrDHNDt7M8P1YeNoAw\"}', '2026-06-21 10:59:51'),
