(4, 5, 'Hi', '```json\n{\n  \"type\": \"message\",\n  \"message\": \"Hi there! Welcome to our store. How can I assist you today?\"\n}\n```', '{\"candidates\": [{\"content\": {\"parts\": [{\"text\": \"```json\\n{\\n  \\\"type\\\": \\\"message\\\",\\n  \\\"message\\\": \\\"Hi there! Welcome to our store. How can I assist you today?\\\"\\n}\\n```\"}], \"role\": \"model\"}, \"finishReason\": \"STOP\", \"index\": 0}], \"usageMetadata\": {\"promptTokenCount\": 547, \"candidatesTokenCount\": 37, \"totalTokenCount\": 628, \"promptTokensDetails\": [{\"modality\": \"TEXT\", \"tokenCount\": 547}], \"thoughtsTokenCount\": 44, \"serviceTier\": \"standard\"}, \"modelVersion\": \"gemini-2.5-flash\", \"responseId\": \"I8U3avqbOfvnnsEP5YLegA4\"}', '2026-06-21 11:04:04'),
(5, 6, 'show me shoes', '```json\n{\n  \"type\": \"sql\",\n  \"action\": \"search_products\",\n  \"query\": \"SELECT id, product_name, selling_price, image_one FROM products WHERE product_name LIKE \'%shoes%\' AND status=1 LIMIT 20\"\n}\n```', '{\"candidates\": [{\"content\": {\"parts\": [{\"text\": \"```json\\n{\\n  \\\"type\\\": \\\"sql\\\",\\n  \\\"action\\\": \\\"search_products\\\",\\n  \\\"query\\\": \\\"SELECT id, product_name, selling_price, image_one FROM products WHERE product_name LIKE \'%shoes%\' AND status=1 LIMIT 20\\\"\\n}\\n```\"}], \"role\": \"model\"}, \"finishReason\": \"STOP\", \"index\": 0}], \"usageMetadata\": {\"promptTokenCount\": 549, \"candidatesTokenCount\": 65, \"totalTokenCount\": 958, \"promptTokensDetails\": [{\"modality\": \"TEXT\", \"tokenCount\": 549}], \"thoughtsTokenCount\": 344, \"serviceTier\": \"standard\"}, \"modelVersion\": \"gemini-2.5-flash\", \"responseId\": \"98U3at6qGq2fnsEPm4OR0Ak\"}', '2026-06-21 11:07:36'),
(6, 7, 'iii', '```json\n{\n  \"type\": \"message\",\n  \"message\": \"Hello there! 😊 How can I assist you today? Please let me know what you\'re looking for or if you have any questions!\"\n}\n```', '{\"candidates\": [{\"content\": {\"parts\": [{\"text\": \"```json\\n{\\n  \\\"type\\\": \\\"message\\\",\\n  \\\"message\\\": \\\"Hello there! \\ud83d\\ude0a How can I assist you today? Please let me know what you\'re looking for or if you have any questions!\\\"\\n}\\n```\"}], \"role\": \"model\"}, \"finishReason\": \"STOP\", \"index\": 0}], \"usageMetadata\": {\"promptTokenCount\": 547, \"candidatesTokenCount\": 50, \"totalTokenCount\": 651, \"promptTokensDetails\": [{\"modality\": \"TEXT\", \"tokenCount\": 547}], \"thoughtsTokenCount\": 54, \"serviceTier\": \"standard\"}, \"modelVersion\": \"gemini-2.5-flash\", \"responseId\": \"p6Q4aqPHItCcjuMPmqa2qQY\"}', '2026-06-22 02:57:44'),
