INSERT INTO `services_faqs` (`id`, `user_id`, `question`, `answer`, `created_at`, `updated_at`) VALUES
(19, 9, 'Do you offer parking?', 'Yes — free customer parking is available.', '2026-07-16 13:37:15', '2026-07-16 13:37:15'),
(20, 9, 'Can I cancel my appointment?', 'Yes. Appointments may be cancelled up to 2 hours before booking.', '2026-07-16 13:37:15', '2026-07-16 13:37:15'),
(21, 9, 'When should I arrive?', 'Please arrive 10 minutes before your appointment.', '2026-07-16 13:37:15', '2026-07-16 13:37:15'),
(22, 9, 'What payment methods do you accept?', 'Cash, Card, JazzCash, and EasyPaisa.', '2026-07-16 13:37:15', '2026-07-16 13:37:15'),
(23, 9, 'Are you open on Sunday?', 'No — we are closed on Sundays.', '2026-07-16 13:37:15', '2026-07-16 13:37:15'),
(24, 9, 'Do you have memberships or packages?', 'Ask about current memberships, packages, and promotions — we will share what is configured.', '2026-07-16 13:37:15', '2026-07-16 13:37:15'),
(25, 12, 'What areas do you cover?', 'We cover all of Dubai including Marina, Downtown, Business Bay, JVC, JLT, Palm Jumeirah and more.', '2026-07-17 09:09:08', '2026-07-17 09:09:08'),
(26, 12, 'Do you bring your own equipment?', 'Yes, our crews arrive fully equipped with eco-friendly supplies.', '2026-07-17 09:09:08', '2026-07-17 09:09:08'),
(27, 12, 'What are your working hours?', 'Monday to Saturday, 08:00 AM to 08:00 PM. Closed on Sunday.', '2026-07-17 09:09:08', '2026-07-17 09:09:08'),
(28, 12, 'How do I pay?', 'We accept Cash, Card, Stripe, Online Payment and Bank Transfer.', '2026-07-17 09:09:08', '2026-07-17 09:09:08'),
(29, 12, 'Can I reschedule?', 'Yes, free rescheduling up to 4 hours before your slot.', '2026-07-17 09:09:08', '2026-07-17 09:09:08'),
(30, 12, 'Do you offer AC cleaning?', 'Yes — AC Duct, Coil and Filter cleaning are available.', '2026-07-17 09:09:08', '2026-07-17 09:09:08'),
(31, 13, 'What are your hours?', 'We are open every day from 09:00 AM to 10:00 PM.', '2026-07-17 09:57:34', '2026-07-17 09:57:34'),
(32, 13, 'Where are you located?', 'Jumeirah, Dubai, UAE — see glamstudio.ae for map.', '2026-07-17 09:57:34', '2026-07-17 09:57:34'),
(33, 13, 'Do you offer bridal packages?', 'Yes — Bridal Glow Package includes makeup, hair and nails.', '2026-07-17 09:57:34', '2026-07-17 09:57:34'),
(34, 13, 'What payment methods do you accept?', 'Cash, Card, Apple Pay, Google Pay, Stripe and Online Payment.', '2026-07-17 09:57:34', '2026-07-17 09:57:34'),
(35, 13, 'Can I cancel or reschedule?', 'Yes, free of charge up to 3 hours before your appointment.', '2026-07-17 09:57:34', '2026-07-17 09:57:34'),
(36, 13, 'Do you sell hair products?', 'Yes, we stock shampoo, serum, masks, colour and tools.', '2026-07-17 09:57:34', '2026-07-17 09:57:34'),
(37, 14, 'What are your hours?', 'We are open every day from 09:00 AM to 10:00 PM.', '2026-07-17 10:37:30', '2026-07-17 10:37:30'),
