(53, 11, '22076232609947@lid', 'Ap k pass kya ha khane ko', '{\"event\": \"message_received\", \"session\": \"user_11\", \"phone\": \"22076232609947@lid\", \"sender_phone\": \"22076232609947@lid\", \"message\": \"Ap k pass kya ha khane ko\", \"text\": \"Ap k pass kya ha khane ko\", \"sender_name\": \"husain\", \"name\": \"husain\", \"number\": \"22076232609947@lid\", \"from\": \"22076232609947@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-17T07:58:19+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"session\": \"user_11\", \"message_log_id\": 278}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"Elite Pizza mein hamare paas ye cheezein hain:\\n\\n**Pizza:** Margherita (1200.0 PKR), Pepperoni (1500.0 PKR), Chicken Fajita (1700.0 PKR), BBQ Chicken (1800.0 PKR), Special Pizza (2200.0 PKR).\\n\\n**Burger:** Zinger Burger (650.0 PKR), Beef Burger (750.0 PKR), Double Patty (950.0 PKR).\\n\\n**Fries:** Regular Fries (250.0 PKR), Loaded Fries (550.0 PKR).\\n\\n**Drinks:** Pepsi (150.0 PKR), 7UP (150.0 PKR), Mountain Dew (150.0 PKR), Mineral Water (100.0 PKR).\\n\\n**Desserts:** Brownie (350.0 PKR), Ice Cream (300.0 PKR).\\n\\nKya lena pasand karenge?\"}}}', 'replied', '2026-07-17 07:58:29'),
(54, 11, '22076232609947@lid', 'Burger', '{\"event\": \"message_received\", \"session\": \"user_11\", \"phone\": \"22076232609947@lid\", \"sender_phone\": \"22076232609947@lid\", \"message\": \"Burger\", \"text\": \"Burger\", \"sender_name\": \"husain\", \"name\": \"husain\", \"number\": \"22076232609947@lid\", \"from\": \"22076232609947@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-17T07:58:44+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"session\": \"user_11\", \"message_log_id\": 280}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"Burger mein hamare paas hain:\\n- Zinger Burger (650.0 PKR)\\n- Beef Burger (750.0 PKR)\\n- Double Patty (950.0 PKR)\\n\\nKaunsa pasand karenge?\"}}}', 'replied', '2026-07-17 07:58:51'),
