(201, 11, '229750819827958@lid', 'Mje pizza purchase krna hy', '{\"event\": \"message_received\", \"session\": \"user_11\", \"phone\": \"229750819827958@lid\", \"sender_phone\": \"229750819827958@lid\", \"message\": \"Mje pizza purchase krna hy\", \"text\": \"Mje pizza purchase krna hy\", \"sender_name\": \"Irfan Kharal\", \"name\": \"Irfan Kharal\", \"number\": \"229750819827958@lid\", \"from\": \"229750819827958@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-17T13:01:42+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"session\": \"user_11\", \"message_log_id\": 10}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"ہمارے پاس یہ پیزا دستیاب ہیں:\\n\\n*   **Margherita** (1200.0 PKR)\\n*   **Pepperoni** (1500.0 PKR)\\n*   **Chicken Fajita** (1700.0 PKR)\\n*   **BBQ Chicken** (1800.0 PKR)\\n*   **Special Pizza** (2200.0 PKR)\\n\\nآپ کون سا پیزا لینا چاہیں گے؟\"}}}', 'replied', '2026-07-17 13:01:48'),
