(232, 17, '229750819827958@lid', 'Helo', '{\"event\": \"message_received\", \"session\": \"user_17\", \"phone\": \"229750819827958@lid\", \"sender_phone\": \"229750819827958@lid\", \"message\": \"Helo\", \"text\": \"Helo\", \"sender_name\": \"Irfan Kharal\", \"name\": \"Irfan Kharal\", \"number\": \"229750819827958@lid\", \"from\": \"229750819827958@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-19T12:20:51+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"type\": \"text\", \"session\": \"user_17\", \"message_log_id\": 152}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"ہیلو! کیسے ہیں آپ؟ میں Elite Pizza میں آپ کی کیا مدد کر سکتی ہوں؟\"}}}', 'replied', '2026-07-19 12:21:09'),
(233, 17, '145702537687288@lid', 'Rate list', '{\"event\": \"message_received\", \"session\": \"user_17\", \"phone\": \"145702537687288@lid\", \"sender_phone\": \"145702537687288@lid\", \"message\": \"Rate list\", \"text\": \"Rate list\", \"sender_name\": \"🇵🇰\", \"name\": \"🇵🇰\", \"number\": \"145702537687288@lid\", \"from\": \"145702537687288@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-19T12:20:56+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"type\": \"text\", \"session\": \"user_17\", \"message_log_id\": 153}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"جی یہ ہماری ریٹ لسٹ ہے:\\n\\n**پیزا**\\n- Margherita: 1200.0 PKR (Small: -200.0, Medium: +0.0, Large: +400.0)\\n- Pepperoni: 1500.0 PKR (Small: -200.0, Medium: +0.0, Large: +400.0)\\n- Chicken Fajita: 1700.0 PKR (Small: -200.0, Medium: +0.0, Large: +400.0)\\n- BBQ Chicken: 1800.0 PKR (Small: -200.0, Medium: +0.0, Large: +400.0)\\n- Special Pizza: 2200.0 PKR (Small: -200.0, Medium: +0.0, Large: +400.0)\\n\\n**برگر**\\n- Zinger Burger: 650.0 PKR\\n- Beef Burger: 750.0 PKR\\n- Double Patty: 950.0 PKR\\n\\n**فرائز**\\n- Regular Fries: 250.0 PKR\\n- Loaded Fries: 550.0 PKR\\n\\n**ڈرنکس**\\n- Pepsi: 150.0 PKR\\n- 7UP: 150.0 PKR\\n- Mountain Dew: 150.0 PKR\\n- Mineral Water: 100.0 PKR\\n\\n**میٹھے**\\n- Brownie: 350.0 PKR\\n- Ice Cream: 300.0 PKR\\n\\nآپ کو کونسی چیز پسند ہے؟\"}}}', 'replied', '2026-07-19 12:21:13'),
(234, 17, '229750819827958@lid', 'I need a pizza', '{\"event\": \"message_received\", \"session\": \"user_17\", \"phone\": \"229750819827958@lid\", \"sender_phone\": \"229750819827958@lid\", \"message\": \"I need a pizza\", \"text\": \"I need a pizza\", \"sender_name\": \"Irfan Kharal\", \"name\": \"Irfan Kharal\", \"number\": \"229750819827958@lid\", \"from\": \"229750819827958@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-19T12:21:01+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"type\": \"text\", \"session\": \"user_17\", \"message_log_id\": 154}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"ہمارے پاس یہ پیزا دستیاب ہیں:\\n\\n*   **Margherita** (کلاسک چیز اور ٹماٹر) - 1200.0 PKR\\n*   **Pepperoni** (لوڈڈ پیپرونی) - 1500.0 PKR\\n*   **Chicken Fajita** (مسالے دار چکن فاہیتا) - 1700.0 PKR\\n*   **BBQ Chicken** (اسمُوکِی باربی کیو چکن) - 1800.0 PKR\\n*   **Special Pizza** (ہاؤس اسپیشل لوڈڈ) - 2200.0 PKR\\n\\nآپ کون سا پیزا پسند کریں گے؟ اور کس سائز میں (Small, Medium, Large)؟\"}}}', 'replied', '2026-07-19 12:21:16'),
(235, 17, '229750819827958@lid', 'Ap k pas kea product hota hy', '{\"event\": \"message_received\", \"session\": \"user_17\", \"phone\": \"229750819827958@lid\", \"sender_phone\": \"229750819827958@lid\", \"message\": \"Ap k pas kea product hota hy\", \"text\": \"Ap k pas kea product hota hy\", \"sender_name\": \"Irfan Kharal\", \"name\": \"Irfan Kharal\", \"number\": \"229750819827958@lid\", \"from\": \"229750819827958@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-19T12:21:16+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"type\": \"text\", \"session\": \"user_17\", \"message_log_id\": 156}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"ہمارے پاس یہ چیزیں دستیاب ہیں:\\n\\n**پیزا:** Margherita, Pepperoni, Chicken Fajita, BBQ Chicken, Special Pizza\\n**برگرز:** Zinger Burger, Beef Burger, Double Patty\\n**فرائز:** Regular Fries, Loaded Fries\\n**ڈرنکس:** Pepsi, 7UP, Mountain Dew, Mineral Water\\n**ڈیزرٹس:** Brownie, Ice Cream\\n\\nآپ کیا آرڈر کرنا چاہیں گے؟\"}}}', 'replied', '2026-07-19 12:21:23');
