(249, 17, '22076232609947@lid', 'Mje piza chaea', '{\"event\": \"message_received\", \"session\": \"user_17\", \"phone\": \"22076232609947@lid\", \"sender_phone\": \"22076232609947@lid\", \"message\": \"Mje piza chaea\", \"text\": \"Mje piza chaea\", \"sender_name\": \"husain\", \"name\": \"husain\", \"number\": \"22076232609947@lid\", \"from\": \"22076232609947@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-19T12:26:06+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"type\": \"text\", \"session\": \"user_17\", \"message_log_id\": 185}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"ہمارے پاس یہ پیزا دستیاب ہیں:\\n\\n*   **Margherita** - 1200.0 PKR (Classic cheese & tomato)\\n*   **Pepperoni** - 1500.0 PKR (Loaded pepperoni)\\n*   **Chicken Fajita** - 1700.0 PKR (Spicy chicken fajita)\\n*   **BBQ Chicken** - 1800.0 PKR (Smoky BBQ chicken)\\n*   **Special Pizza** - 2200.0 PKR (House special loaded)\\n\\nآپ کون سا پیزا لینا چاہیں گے؟\"}}}', 'replied', '2026-07-19 12:26:37'),
(250, 17, '145861401116758@lid', 'G nhi sir', '{\"event\": \"message_received\", \"session\": \"user_17\", \"phone\": \"145861401116758@lid\", \"sender_phone\": \"145861401116758@lid\", \"message\": \"G nhi sir\", \"text\": \"G nhi sir\", \"sender_name\": \"بابر رحمان خان\", \"name\": \"بابر رحمان خان\", \"number\": \"145861401116758@lid\", \"from\": \"145861401116758@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-19T12:26:37+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"type\": \"text\", \"session\": \"user_17\", \"message_log_id\": 187}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"کوئی بات نہیں، جب آپ کو کچھ آرڈر کرنا ہو تو بس مجھے بتا دیجیے گا۔\"}}}', 'replied', '2026-07-19 12:26:45'),
(251, 17, '145702537687288@lid', 'Order kB punchy ga', '{\"event\": \"message_received\", \"session\": \"user_17\", \"phone\": \"145702537687288@lid\", \"sender_phone\": \"145702537687288@lid\", \"message\": \"Order kB punchy ga\", \"text\": \"Order kB punchy ga\", \"sender_name\": \"🇵🇰\", \"name\": \"🇵🇰\", \"number\": \"145702537687288@lid\", \"from\": \"145702537687288@lid\", \"wpp_event\": \"onmessage\", \"received_at\": \"2026-07-19T12:27:24+00:00\"}', 1, '923004210607', '{\"notify\": {}, \"reply\": {\"ok\": true, \"sent\": true, \"type\": \"text\", \"session\": \"user_17\", \"message_log_id\": 189}, \"ai\": {\"handler_class\": \"Restaurant\", \"action_only\": false, \"success\": true, \"reply_json\": {\"type\": \"message\", \"message\": \"آپ کا آرڈر اندازاً 30 سے 45 منٹ میں پہنچ جائے گا۔\\nبراہ کرم ڈیلیوری کے لیے اپنا مکمل پتا (اسٹریٹ نمبر اور علاقہ) اور ادائیگی کا طریقہ بتائیں۔\"}}}', 'replied', '2026-07-19 12:27:30'),
